#!/usr/bin/env python3
"""Version-locked collector fixes. Existing timers restored; application untouched."""
import base64,datetime as dt,fcntl,gzip,hashlib,json,os,pathlib,re,sqlite3,subprocess,tempfile,time

BUNDLE=''
FB=pathlib.Path('/opt/umraniye-osint-facebook-fbgql-deneme')
IG=pathlib.Path('/opt/umraniye-osint-instagram-api')
TIMERS=['umraniye-osint-facebook-fbgql-deneme.timer','umraniye-osint-instagram-api.timer']
SERVICES=['umraniye-osint-facebook-fbgql-deneme.service','umraniye-osint-instagram-api.service']
PRESERVED=['umraniye-osint-deneme.service','umraniye-osint.service','umraniye-telegram.service','umraniye-osint-x-twscrape-deneme.timer']

def run(args,timeout=30):return subprocess.run(args,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=timeout)
def state(unit):
 result=run(['systemctl','show',unit,'-p','ActiveState','-p','ExecMainStartTimestampMonotonic','-p','LastTriggerUSec'])
 return dict(l.split('=',1) for l in result.stdout.splitlines() if '=' in l)
def digest(data):return hashlib.sha256(data).hexdigest()
def put(path,data,stat=None):
 path=pathlib.Path(path);temp=path.with_name(path.name+'.quality-tmp')
 with temp.open('wb') as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
 os.chmod(temp,stat.st_mode & 0o777 if stat else 0o644)
 if stat:os.chown(temp,stat.st_uid,stat.st_gid)
 os.replace(temp,path)

def main():
 if os.geteuid()!=0:raise RuntimeError('sudo_required')
 with open('/run/osint-reading-quality-install.lock','a') as lock:
  fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
  install_locked()

def install_locked():
 bundle=json.loads(gzip.decompress(base64.b64decode(BUNDLE)))
 rows=bundle['files'];targets={str(FB/'worker.py'),str(IG/'worker.py'),'/opt/umraniye-osint-deneme/scripts/osint-reading-audit.py'}
 if {r['target'] for r in rows}!=targets:raise RuntimeError('invalid_install_targets')
 originals={};stats={};changed=[]
 for row in rows:
  path=pathlib.Path(row['target']);data=base64.b64decode(row['content'])
  if path.is_symlink() or path.parent.is_symlink():raise RuntimeError('symlink_target_rejected')
  old=path.read_bytes() if path.exists() else None
  if old==data:continue
  if (digest(old) if old is not None else None)!=row['expected']:raise RuntimeError('version_changed_no_install:'+path.name)
  if path.exists() and path.stat().st_nlink!=1:raise RuntimeError('shared_file_no_install')
  originals[str(path)]=old;stats[str(path)]=path.stat() if path.exists() else None;changed.append(row)
 with tempfile.TemporaryDirectory(prefix='osint-quality-check-') as directory:
  stage=pathlib.Path(directory)
  for name,content in bundle['tests'].items():
   if name not in ('facebook/worker.py','instagram/worker.py','reading_audit.py','tests/test_quality.py'):raise RuntimeError('invalid_test_target')
   p=stage/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(content))
  test=run(['python3',str(stage/'tests/test_quality.py')],45)
  if test.returncode or 'skipped=' in test.stderr:raise RuntimeError('offline_checks_failed_no_install')
  matched=re.search(r'Ran (\d+) tests',test.stderr)
  if not matched:raise RuntimeError('offline_test_count_unverified')
  test_count=int(matched[1])
 before={u:state(u) for u in PRESERVED}
 previous_timers={u:state(u).get('ActiveState') in ('active','activating') for u in TIMERS}
 backup=pathlib.Path('/var/lib/umraniye-osint-deneme/backups')/('reading-quality-'+dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
 backup.mkdir(mode=0o700,parents=True)
 old_manifest={n:{'data':base64.b64encode(v).decode() if v is not None else None,
  'mode':stats[n].st_mode & 0o777 if stats[n] else 0o644,'uid':stats[n].st_uid if stats[n] else 0,'gid':stats[n].st_gid if stats[n] else 0} for n,v in originals.items()}
 (backup/'files.json').write_text(json.dumps(old_manifest));os.chmod(backup/'files.json',0o600)
 rollback='''#!/usr/bin/env python3
import base64,json,os,pathlib,subprocess,time
base=pathlib.Path(__file__).resolve().parent
timers=__TIMERS__
services=__SERVICES__
previous={u:subprocess.run(['systemctl','is-active','--quiet',u]).returncode==0 for u in timers}
try:
 for u in timers:subprocess.run(['systemctl','stop',u],check=True)
 deadline=time.monotonic()+240
 while any(subprocess.check_output(['systemctl','show',u,'-p','ActiveState','--value'],text=True).strip() in ('active','activating','deactivating') for u in services):
  if time.monotonic()>deadline:raise RuntimeError('collector_busy_no_rollback')
  time.sleep(2)
 for name,row in json.loads((base/'files.json').read_text()).items():
  p=pathlib.Path(name)
  if row['data'] is None:p.unlink(missing_ok=True);continue
  t=p.with_name(p.name+'.rollback-tmp');t.write_bytes(base64.b64decode(row['data']));os.chmod(t,row['mode']);os.chown(t,row['uid'],row['gid']);os.replace(t,p)
 print('Kod geri alındı. Yeni kayıtlar ve Telegram geçmişi korunur; site yeniden başlatılmadı.')
finally:
 for u,enabled in previous.items():
  if enabled:subprocess.run(['systemctl','start',u],check=True)
'''.replace('__TIMERS__',repr(TIMERS)).replace('__SERVICES__',repr(SERVICES))
 (backup/'geri-al.py').write_text(rollback,encoding='utf-8');os.chmod(backup/'geri-al.py',0o700)
 written=[];locks=[]
 print('Sürümler ve '+str(test_count)+' izole kontrol geçti. İki toplayıcının mevcut turu beklenecek; site yeniden başlatılmayacak.',flush=True)
 try:
  for timer,was_active in previous_timers.items():
   if was_active and run(['systemctl','stop',timer]).returncode:raise RuntimeError('timer_pause_failed')
  deadline=time.monotonic()+240;next_update=0
  while any(state(u).get('ActiveState') in ('active','activating','deactivating') for u in SERVICES):
   if time.monotonic()>deadline:raise RuntimeError('collector_busy_no_install')
   if time.monotonic()>next_update:print('Mevcut tarama bitiyor; profil ve kayıtlar korunuyor...',flush=True);next_update=time.monotonic()+30
   time.sleep(2)
  for directory in ['/var/lib/umraniye-osint-facebook-fbgql-deneme','/var/lib/umraniye-osint-instagram-api']:
   f=open(pathlib.Path(directory)/'run.lock','a');locks.append(f);fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB)
  # Consistent private queue snapshots. Rollback does not erase post-install records.
  for name,path in [('facebook',pathlib.Path('/var/lib/umraniye-osint-facebook-fbgql-deneme/shadow.sqlite')),('instagram',pathlib.Path('/var/lib/umraniye-osint-instagram-api/queue.sqlite'))]:
   src=sqlite3.connect(path.resolve().as_uri()+'?mode=ro',uri=True,timeout=5);target=backup/(name+'-queue.sqlite');dest=sqlite3.connect(target)
   try:src.backup(dest)
   finally:dest.close();src.close()
   os.chmod(target,0o600)
  for row in changed:
   p=pathlib.Path(row['target']);current=p.read_bytes() if p.exists() else None
   if current!=originals[str(p)]:raise RuntimeError('version_changed_during_wait')
  for row in changed:
   p=pathlib.Path(row['target']);put(p,base64.b64decode(row['content']),stats[str(p)]);written.append(str(p))
  if any(pathlib.Path(r['target']).read_bytes()!=base64.b64decode(r['content']) for r in rows):raise RuntimeError('post_install_content_mismatch')
 except Exception:
  for name in reversed(written):
   if originals[name] is None:pathlib.Path(name).unlink(missing_ok=True)
   else:put(name,originals[name],stats[name])
  raise
 finally:
  for f in locks:f.close()
  for timer,was_active in previous_timers.items():
   if was_active and run(['systemctl','start',timer]).returncode:print('UYARI: Zamanlayıcı tekrar başlatılamadı: '+timer,flush=True)
 after={u:state(u) for u in PRESERVED}
 timer_states={u:state(u).get('ActiveState') for u in TIMERS}
 timers_ok=all((timer_states[u] in ('active','activating'))==was_active for u,was_active in previous_timers.items())
 report={'result':'collector_quality_v1_installed','at':dt.datetime.now(dt.timezone.utc).isoformat(),
  'changedFiles':[r['target'] for r in changed],'offlineTestsPassed':test_count,'applicationRestarted':False,
  'telegramSettingsChanged':False,'historicalReplay':False,'browserOrAPIScanForced':False,'newTimers':0,
  'workerIntervalsChanged':False,'databaseEditedByInstaller':False,'privateQueueBackupsTaken':True,
  'applicationAndProductionStartTimesPreserved':all(before[u].get('ExecMainStartTimestampMonotonic')==after[u].get('ExecMainStartTimestampMonotonic') for u in PRESERVED),
  'timerStatesRestored':timer_states,'timerRestoreVerified':timers_ok,'newLivePostVerified':False,'scoresRecalculated':False,
  'auditCommand':'sudo python3 /opt/umraniye-osint-deneme/scripts/osint-reading-audit.py',
  'backup':str(backup),'rollback':'sudo python3 '+str(backup/'geri-al.py')}
 audit=run(['python3','/opt/umraniye-osint-deneme/scripts/osint-reading-audit.py'],100)
 if audit.returncode==0:
  try:
   evidence=json.loads(audit.stdout)
   (backup/'reading-evidence.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2));os.chmod(backup/'reading-evidence.json',0o600)
   report['operationalEvidence']={k:{field:v.get(field) for field in ['rounds','readableRounds','latestRoundAgeMinutes','roundStatuses']} for k,v in evidence.get('channels',{}).items()}
   report['instagramDecisionReasons']=evidence.get('instagramDecisions')
  except ValueError:report['auditStatus']='invalid_json'
 else:report['auditStatus']='unavailable'
 if not timers_ok:report['result']='collector_quality_installed_scheduler_attention_required'
 (backup/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report,ensure_ascii=False,indent=2))
 if not timers_ok:raise RuntimeError('timer_restore_requires_attention')

if __name__=='__main__':
 try:main()
 except Exception as error:print('KURULUM TAMAMLANAMADI: '+str(error)[:250]);raise SystemExit(1)
